mkdeclimpl! {
impl < S : squeue :: EntryMarker , C : cqueue :: EntryMarker > IoUring < S , C > { # [doc = " Create a [`Builder`] for an `IoUring` instance."] # [doc = ""] # [doc = " This allows for further customization than [`new`](Self::new)."] # [doc = ""] # [doc = " Unlike [`IoUring::new`], this function is available for any combination of submission"] # [doc = " queue entry (SQE) and completion queue entry (CQE) types."] # [must_use] pub fn builder () -> Builder < S , C > { Builder { dontfork : false , params : sys :: io_uring_params { flags : S :: BUILD_FLAGS | C :: BUILD_FLAGS , .. Default :: default () } , phantom : PhantomData , } } fn with_params (entries : u32 , mut p : sys :: io_uring_params) -> io :: Result < Self > { let fd : OwnedFd = unsafe { OwnedFd :: from_raw_fd (sys :: io_uring_setup (entries , & mut p) ?) } ; unsafe { Self :: with_fd_and_params (fd , p) } } unsafe fn with_fd_and_params (fd : OwnedFd , p : sys :: io_uring_params) -> io :: Result < Self > { # [inline] unsafe fn setup_queue < S : squeue :: EntryMarker , C : cqueue :: EntryMarker > (fd : & OwnedFd , p : & sys :: io_uring_params ,) -> io :: Result < (MemoryMap , squeue :: Inner < S > , cqueue :: Inner < C >) > { let sq_len = p . sq_off . array as usize + p . sq_entries as usize * mem :: size_of :: < u32 > () ; let cq_len = p . cq_off . cqes as usize + p . cq_entries as usize * mem :: size_of :: < C > () ; let sqe_len = p . sq_entries as usize * mem :: size_of :: < S > () ; let sqe_mmap = Mmap :: new (fd , sys :: IORING_OFF_SQES as _ , sqe_len) ? ; if p . features & sys :: IORING_FEAT_SINGLE_MMAP != 0 { let scq_mmap = Mmap :: new (fd , sys :: IORING_OFF_SQ_RING as _ , cmp :: max (sq_len , cq_len)) ? ; let sq = squeue :: Inner :: new (& scq_mmap , & sqe_mmap , p) ; let cq = cqueue :: Inner :: new (& scq_mmap , p) ; let mm = MemoryMap { sq_mmap : scq_mmap , cq_mmap : None , sqe_mmap , } ; Ok ((mm , sq , cq)) } else { let sq_mmap = Mmap :: new (fd , sys :: IORING_OFF_SQ_RING as _ , sq_len) ? ; let cq_mmap = Mmap :: new (fd , sys :: IORING_OFF_CQ_RING as _ , cq_len) ? ; let sq = squeue :: Inner :: new (& sq_mmap , & sqe_mmap , p) ; let cq = cqueue :: Inner :: new (& cq_mmap , p) ; let mm = MemoryMap { cq_mmap : Some (cq_mmap) , sq_mmap , sqe_mmap , } ; Ok ((mm , sq , cq)) } } let (mm , sq , cq) = unsafe { setup_queue (& fd , & p) ? } ; Ok (IoUring { sq , cq , fd , params : Parameters (p) , memory : ManuallyDrop :: new (mm) , }) } # [doc = " Get the submitter of this io_uring instance, which can be used to submit submission queue"] # [doc = " events to the kernel for execution and to register files or buffers with it."] # [inline] pub fn submitter (& self) -> Submitter < '_ > { Submitter :: new (& self . fd , & self . params , self . sq . head , self . sq . tail , self . sq . flags ,) } # [doc = " Get the parameters that were used to construct this instance."] # [inline] pub fn params (& self) -> & Parameters { & self . params } # [doc = " Initiate asynchronous I/O. See [`Submitter::submit`] for more details."] # [inline] pub fn submit (& self) -> io :: Result < usize > { self . submitter () . submit () } # [doc = " Initiate and/or complete asynchronous I/O. See [`Submitter::submit_and_wait`] for more"] # [doc = " details."] # [inline] pub fn submit_and_wait (& self , want : usize) -> io :: Result < usize > { self . submitter () . submit_and_wait (want) } # [doc = " Get the submitter, submission queue and completion queue of the io_uring instance. This can"] # [doc = " be used to operate on the different parts of the io_uring instance independently."] # [doc = ""] # [doc = " If you use this method to obtain `sq` and `cq`,"] # [doc = " please note that you need to `drop` or `sync` the queue before and after submit,"] # [doc = " otherwise the queue will not be updated."] # [inline] pub fn split (& mut self ,) -> (Submitter < '_ > , SubmissionQueue < '_ , S > , CompletionQueue < '_ , C > ,) { let submit = Submitter :: new (& self . fd , & self . params , self . sq . head , self . sq . tail , self . sq . flags ,) ; (submit , self . sq . borrow () , self . cq . borrow ()) } # [doc = " Get the submission queue of the io_uring instance. This is used to send I/O requests to the"] # [doc = " kernel."] # [inline] pub fn submission (& mut self) -> SubmissionQueue < '_ , S > { self . sq . borrow () } # [doc = " Get the submission queue of the io_uring instance from a shared reference."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " No other [`SubmissionQueue`]s may exist when calling this function."] # [inline] pub unsafe fn submission_shared (& self) -> SubmissionQueue < '_ , S > { self . sq . borrow_shared () } # [doc = " Get completion queue of the io_uring instance. This is used to receive I/O completion"] # [doc = " events from the kernel."] # [inline] pub fn completion (& mut self) -> CompletionQueue < '_ , C > { self . cq . borrow () } # [doc = " Get the completion queue of the io_uring instance from a shared reference."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " No other [`CompletionQueue`]s may exist when calling this function."] # [inline] pub unsafe fn completion_shared (& self) -> CompletionQueue < '_ , C > { self . cq . borrow_shared () } }
}